import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Görseldeki metin, okunmuyorsa işe yaramaz. En güzel tasarım bile, yazısı okunamıyorsa başarısızdır.</p>\n<p>Okunabilirlik, stilden önemlidir. Kontrast, boyut ve konum; üçü doğruysa metin herkese ulaşır.</p>\n<p>Bu yazı, kontrast kurallarını, yazı tipi seçimini ve metni kalabalık fotoğraflarda okunur tutmanın yollarını anlatıyor.</p>\n<h2 id=\"why-readability-matters\">Okunabilirlik stilden neden daha önemlidir?</h2>\n<p>Yazı okunmuyorsa mesaj da iletilemez; okur, yazıyı çözemediği görselde durmaz, geçer.</p>\n<p>Okunabilirlik, erişilebilirliktir. Yaşlı ve görme sorunu olan okurlar, düşük kontrastlı metni okuyamaz.</p>\n<p>Stil, okunabilirlikten sonra gelir. Önce metin okunsun, sonra güzel görünsün.</p>\n<h2 id=\"contrast-ratio-basics\">Kontrast: en önemli kural</h2>\n<p>Kontrast, metin ile arka plan arasındaki farktır. Fark büyükse metin okunur; küçükse kaybolur.</p>\n<p>Beyaz metin koyu zeminde, siyah metin açık zeminde okunur. Kural basittir.</p>\n<p>Kontrastı göz kararı değil, araçla ölçün. Kontrast denetleyiciler, oranı sayıyla verir.</p>\n<h2 id=\"choosing-text-colour\">İşe yarayan bir metin rengi seçmek</h2>\n<p>Yazı rengini zemine göre seçin; koyu fotoğrafta beyaz, açık fotoğrafta siyah yazı okunur.</p>\n<p>Marka rengi tercih edebilirsiniz. Renk markayı duyurur; okunabilirlik ise her şeyden önce gelir.</p>\n<p>Renk körü okurları hesaba katın; kırmızı ile yeşil arasındaki ayrım, bazı gözlere hiç görünmez.</p>\n<h2 id=\"choosing-background-areas\">Metni en düz alana koymak</h2>\n<p>Metni, fotoğrafın düz alanına koyun. Gökyüzü, duvar ve deniz, metin için idealdir.</p>\n<p>Kalabalık bölge, yazıyı okunmaz yapar. Ağaçlar ve desenler, harflerin arasında kaybolur.</p>\n<p>Düz alan yoksa panel kullanın. Yarı saydam koyu panel, metni her zeminde okunur yapar.</p>\n<h2 id=\"font-choice\">Yazı tipi seçimi: süslüden önce okunur</h2>\n<p>Sade yazı tipleri okunaklıdır. Kalın ve temiz harfler, fotoğrafta kaybolmaz.</p>\n<p>Süslü yazı tipleri okunması zordur. El yazısı ve dekoratif tipler, küçük boyutta okunamaz.</p>\n<p>Tek görselde en fazla iki yazı tipi kullanın. Fazla tip, karmaşa yaratır.</p>\n<h2 id=\"font-size-rules\">Yazı tipi boyutu: en küçük ekran için yeterince büyük</h2>\n<p>Metin, telefondan okunmalıdır. Küçük yazı, akışta kaybolur.</p>\n<p>Başlık, görsel genişliğinin yüzde 10-15'i kadar olabilir. Alt yazı daha küçük olabilir.</p>\n<p>Boyutu telefon boyutunda test edin. Küçük ekranda okunmayan metin işe yaramaz.</p>\n<h2 id=\"line-length-and-spacing\">Satır uzunluğu ve aralık</h2>\n<p>Uzun metni kısa satırlara bölün. Kısa satırlar, uzun satırlardan kolay okunur.</p>\n<p>Satır aralığını düzenleyin. Sıkışık satırlar, metni boğar.</p>\n<p>Kelime başına satır kırmayın. Satır sonu, kelimenin ortasında olmamalıdır.</p>\n<h2 id=\"outlines-and-shadows\">Kontur ve gölge</h2>\n<p>Kontur, metni her arka planda okunur kılar. Beyaz yazıya siyah kontur her zeminde görünür.</p>\n<p>Gölge, metne derinlik katar. Hafif gölge yazıyı fotoğraftan ayırır.</p>\n<p>İkisini birlikte abartmayın. Kalın konturla koyu gölge, metni ağır gösterir.</p>\n<h2 id=\"background-panels\">Arka plan panelleri ve katmanlar</h2>\n<p>Yarı saydam panel, her fotoğrafta yazıyı kurtarır; koyu panel üstüne beyaz yazı neredeyse her zeminde okunur.</p>\n<p>Paneli fazla kapatmayın; fotoğraf, yarı saydam panelin arkasından belli belirsiz de olsa görünmelidir.</p>\n<p>Panel köşelerini yuvarlatın; keskin köşeli panel, yumuşak fotoğrafın üstünde sert durur.</p>\n<h2 id=\"text-over-busy-photos\">Kalabalık fotoğrafların üzerine metin</h2>\n<p>Kalabalık fotoğrafta metin zordur. Önce arka planı bulanıklaştırın; yazı düz zeminde okunur.</p>\n<p>Panel kullanın. Yarı saydam koyu panel, kalabalık zemini sakinleştirir.</p>\n<p>Metni kısa tutun. Kalabalık fotoğrafta uzun metin okunmaz.</p>\n<h2 id=\"text-over-faces\">Yüzlerin üzerine metin: nelerden kaçınmalı?</h2>\n<p>Yüzün üzerine metin koymayın. Hem yüz hem yazı bozulur.</p>\n<p>Metni yüzün yanına koyun. Boş alan, yazı için idealdir.</p>\n<p>Portrelerde metni alta koyun. Alt kenar, genellikle boştur.</p>\n<h2 id=\"hierarchy\">Hiyerarşi: başlık, alt yazı ve kaynak</h2>\n<p>Başlık büyük, alt yazı orta, kaynak küçük yazılır. Boyut farkı, okurun gözünü yönlendirir.</p>\n<p>Bir görselde bir başlık olmalıdır. İki başlık, gözü şaşırtır.</p>\n<p>Kaynağı küçük ama okunur tutun. Kaynak, görselin güvenilirliğini gösterir.</p>\n<h2 id=\"testing-small-screens\">Küçük ekranlarda test etmek</h2>\n<p>Tasarımı telefon boyutuna indirip yazıyı okuyun; geniş ekranda rahat okunan metin, cepte kaybolabilir.</p>\n<p>Son kontrolde görseli küçültün; küçük hâliyle okunamayan yazı, telefon akışında hiç şans bulamaz.</p>\n<p>Tasarımı bitirince bir arkadaşınıza gösterin; dürüst bir yorum, gözden kaçan okuma sorunlarını ortaya çıkarır.</p>\n<h2 id=\"accessibility\">Erişilebilirlik: herkesin okuyabileceği metin</h2>\n<p>Kontrasttan kısmayın; silik yazı, görme zorluğu yaşayan okurları dışarıda bırakır.</p>\n<p>Yazı tipini sade tutun. Süslü tipler, disleksi olan okurlara zor gelir.</p>\n<p>Alternatif metin ekleyin. Görsel açılmazsa okur, metinden görseli anlar.</p>\n<h2 id=\"common-readability-mistakes\">Yaygın okunabilirlik hataları</h2>\n<p>En yaygın hata düşük kontrasttır. Açık fotoğrafta beyaz yazı kaybolur.</p>\n<p>Bir başka hata, çok küçük metindir. Telefonda okunamayan yazı, işe yaramaz.</p>\n<p>Üçüncü hata, kalabalık zemindir. Desenli arka plan, harfleri yutar.</p>\n<h2 id=\"readability-checklist\">Yayınlamadan önce okunabilirlik listesi</h2>\n<p>Yazıyı zeminden ayıran fark yeterince belirgin mi? Fark silikse okur yazıyı seçemez.</p>\n<p>Yazıyı kendi telefonunuzda açıp bakın; küçük ekranda test edilmemiş metin, yayında sürpriz yapar.</p>\n<p>Yazı yüzleri kapatmıyor, kontrast yerinde ve panel ölçülüyse görseli gönül rahatlığıyla paylaşabilirsiniz.</p>\n<p>Özetle: önce okunabilirlik, sonra stil. Adımlar için <a href=\"/tr/blog/gorsele-metin-nasil-eklenir\">Görsele metin nasıl eklenir</a> yazısına bakın; kılavuzun tamamı <a href=\"/tr/blog/gorsele-metin-ekle-rehberi\">Görsele metin ekleme kılavuzunda</a>. Filigran için <a href=\"/tr/gorsel-filigran-ekle\">görsel filigran</a> hazırdır; araç ise <a href=\"/tr/gorsele-metin-ekle\">görsele metin ekleme</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Fotoğraftaki metni okunması zor yapan nedir?","answer":"Düşük kontrast, küçük boyut ve kalabalık zemin. Açık fotoğrafta beyaz yazı kaybolur; telefonda küçük yazı okunamaz; desenli arka plan harfleri yutar. Çözüm: kontrastı artırın, boyutu büyütün ve metni düz alana koyun."},{"question":"Fotoğraftaki metin için kontur mu gölge mi kullanmalıyım?","answer":"İkisi de işe yarar; kontur daha güvenlidir. Beyaz yazıya siyah kontur, her zeminde görünür. Gölge, metne derinlik verir ama kalabalık zeminde yetersiz kalır. İkisini birlikte abartmayın."},{"question":"Telefon akışı için görseldeki metin ne kadar büyük olmalı?","answer":"Telefondan okunacak kadar büyük olmalıdır. Başlık, görsel genişliğinin yüzde 10-15'i kadar olabilir. Boyutu telefon boyutunda test edin; küçük ekranda okunmayan metin işe yaramaz."},{"question":"Fotoğrafta metin koymak için en iyi yer neresidir?","answer":"Fotoğrafın en düz alanıdır: gökyüzü, duvar ya da deniz. Yüzlerin üzerine metin koymayın; hem yüz hem yazı bozulur. Düz alan yoksa yarı saydam koyu panel kullanın."},{"question":"Bir görselde kaç yazı tipi kullanmalıyım?","answer":"En fazla iki. Başlık için kalın, alt yazı için sade tip seçin. Fazla tip karmaşa yaratır ve görseli amatör gösterir. Tutarlılık, profesyonel görünüm yaratır."},{"question":"Metin rengi, renk körü izleyiciler için önemli mi?","answer":"Evet. Kırmızı ile yeşil arasındaki fark, bazı okurlara görünmez. Renk farkına değil, parlaklık farkına güvenin; koyu zeminde açık yazı, açık zeminde koyu yazı kullanın. Kontrastı araçla ölçün."}];
